def score_up(s,i):
    up=s[max(0,i-14):i]
    # purine rich
    pur=sum(1 for c in up if c in 'AG')
    # SD-like: presence of GGAGG-ish
    m=re.search(r'[AG]{4,}', up)
    return up,pur,bool(m), (m.group() if m else '')

