import re
seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
L=len(seq)
comp = str.maketrans("ACGT","TGCA")
rc = seq.translate(comp)[::-1]
stops={"TAA","TAG","TGA"}

def next_stop(s,start,f):
    i=start
    while i+3<=len(s):
        if s[i:i+3] in stops:
            return i
        i+=3
    return len(s)

def analyze(s,name):
    n=len(s)
    print("=====",name)
    for f in range(3):
        for i in range(f,n-2,3):
            if s[i:i+3] in stops:
                pre=s[max(0,i-9):i]
                runs=re.findall(r'(A{5,}|T{5,}|G{5,}|C{5,})',pre)
                if runs:
                    # distance from run end to stop start
                    # find last run
                    for m in re.finditer(r'(A{5,}|T{5,}|G{5,}|C{5,})',pre):
                        run_end = max(0,i-9)+m.end()
                        dist = i-run_end
                        if dist<=2:
                            for shift,lab in [(1,'+1'),(-1,'-1')]:
                                nf=(f+shift)%3
                                # downstream in frame nf: find first stop after i
                                ns=next_stop(s,i+dist+ ( (nf-f)%3 ),nf)
                                ext=ns-(i)
                                print(f"{name} f{f} stop {s[i:i+3]} at {i+1} run {m.group()} dist {dist} | {lab}->frame{nf} downstream ORF ~{ext}nt")
    return

analyze(seq,"FWD")
analyze(rc,"REV")

